/**
 * Dependency security regression tests. Nothing here is mocked: every project is generated by the real CLI, installed from the
 * real registry and audited by the real `npm audit`. A vulnerable, deprecated or misaligned dependency makes these tests fail.
 * Slow (npm install per project). Run with: npm run test:e2e
 */
import { spawn, spawnSync, type SpawnSyncReturns } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

const root = resolve(import.meta.dirname, "../..");
const win = process.platform === "win32";
const work = mkdtempSync(join(tmpdir(), "rhea-sec-"));
const tgz = join(work, "tgz");
const node = process.execPath;
let env: NodeJS.ProcessEnv;

const gitIdentity = {
  GIT_AUTHOR_NAME: "Test",
  GIT_AUTHOR_EMAIL: "test@example.invalid",
  GIT_COMMITTER_NAME: "Test",
  GIT_COMMITTER_EMAIL: "test@example.invalid",
};
const sh = (cmd: string, args: string[], cwd: string, extra: NodeJS.ProcessEnv = {}): SpawnSyncReturns<string> =>
  spawnSync(cmd, args, {
    cwd,
    encoding: "utf8",
    shell: win && (cmd === "npm" || cmd === "git"),
    env: { ...process.env, ...extra },
    maxBuffer: 64 * 1024 * 1024,
    timeout: 280_000,
  });
const npm = (args: string[], cwd: string) => sh("npm", args, cwd);
const git = (args: string[], cwd: string) => sh("git", args, cwd);
const rhea = (args: string[], cwd: string) => sh(node, [join(root, "packages/cli/dist/bin.js"), ...args], cwd, { ...env, ...gitIdentity });
const show = (r: SpawnSyncReturns<string>) => `${r.stdout}\n${r.stderr}`;
const sha = (file: string) => createHash("sha256").update(readFileSync(file)).digest("hex");

/** Runs `npm audit` for real and fails with the advisory report when anything at all is found. */
function expectCleanAudit(cwd: string, label: string): void {
  const r = npm(["audit", "--audit-level=low", "--json"], cwd);
  const report = JSON.parse(r.stdout || "{}") as { metadata?: { vulnerabilities?: Record<string, number> } };
  const counts = report.metadata?.vulnerabilities;
  expect(counts, `${label}: no audit report\n${show(r)}`).toBeDefined();
  expect(counts, `${label}: ${JSON.stringify(counts)}\n${npm(["audit"], cwd).stdout}`).toMatchObject({
    info: 0,
    low: 0,
    moderate: 0,
    high: 0,
    critical: 0,
    total: 0,
  });
  expect(r.status, `${label}: npm audit exit code\n${show(r)}`).toBe(0);
}

beforeAll(() => {
  mkdirSync(tgz);
  expect(npm(["run", "build"], root).status).toBe(0);
  for (const w of ["@rheajs/core", "@rheajs/auth", "@rheajs/cli", "create-rhea"])
    expect(npm(["pack", "-w", w, "--pack-destination", tgz], root).status).toBe(0);
  const f = (p: string) =>
    "file:" +
    join(
      tgz,
      readdirSync(tgz).find((x) => x.startsWith(p))!,
    );
  env = { RHEA_CORE_SPEC: f("rheajs-core"), RHEA_AUTH_SPEC: f("rheajs-auth"), RHEA_CLI_SPEC: f("rheajs-cli") };
}, 300_000);
afterAll(() => rmSync(work, { recursive: true, force: true }));

describe("framework and generator packages", () => {
  it("the monorepo (framework, tooling, docs, website) audits clean", () => {
    expectCleanAudit(root, "monorepo");
  });

  it("create-rhea and @rheajs/cli install from their published tarballs and audit clean", () => {
    const dir = join(work, "installed-generator");
    mkdirSync(dir);
    writeFileSync(join(dir, "package.json"), JSON.stringify({ name: "generator-check", private: true }));
    const f = (p: string) =>
      join(
        tgz,
        readdirSync(tgz).find((x) => x.startsWith(p))!,
      );
    const i = npm(["install", "--no-fund", f("rheajs-core"), f("rheajs-auth"), f("rheajs-cli"), f("create-rhea")], dir);
    expect(i.status, show(i)).toBe(0);
    expectCleanAudit(dir, "create-rhea tarballs");
    const prod = npm(["audit", "--omit=dev", "--audit-level=low"], dir);
    expect(prod.status, show(prod)).toBe(0);
  }, 300_000);
});

const combos = [
  ...(["ts", "js"] as const).flatMap((language) =>
    (["esm", "cjs"] as const).flatMap((module) => (["none", "mongodb", "mysql"] as const).map((db) => ({ language, module, db, auth: false }))),
  ),
  { language: "ts", module: "esm", db: "mysql", auth: true },
  { language: "js", module: "cjs", db: "mongodb", auth: true },
] as const;
const nameOf = (c: (typeof combos)[number]) => `${c.language}-${c.module}-${c.db}${c.auth ? "-auth" : ""}`;
const secrets = new Map<string, string>();

describe.each(combos)("generated project $language / $module / $db / auth=$auth", (c) => {
  const name = nameOf(c);
  const app = join(work, name);

  it("installs from scratch with no deprecation warning and no blocked required install script", () => {
    const flags = ["--" + c.language, "--" + c.module, "--db", c.db, ...(c.auth ? ["--auth"] : [])];
    const r = rhea(["create", name, ...flags, "--yes", "--install"], work);
    expect(r.status, show(r)).toBe(0);
    expect(existsSync(join(app, "package-lock.json"))).toBe(true);
    const again = npm(["install", "--no-fund", "--no-audit"], app);
    expect(again.status, show(again)).toBe(0);
    expect(show(again)).not.toMatch(/npm warn deprecated/i);
    expect(show(again)).not.toMatch(/install scripts? .*blocked/i);
  }, 300_000);

  it("npm audit reports zero vulnerabilities, development dependencies included", () => {
    expectCleanAudit(app, name);
  });

  it("has aligned test tooling, no nodemon, and a working esbuild and tsx", () => {
    const pkg = JSON.parse(readFileSync(join(app, "package.json"), "utf8"));
    expect(pkg.devDependencies.vitest).toBe(pkg.devDependencies["@vitest/coverage-v8"]);
    expect(pkg.devDependencies.nodemon).toBeUndefined();
    expect(existsSync(join(app, "nodemon.json"))).toBe(false);
    expect(pkg.engines.node).toBe(">=22.13.0");
    expect(pkg.allowScripts).toEqual(c.language === "ts" ? { esbuild: true } : undefined);
    const lock = JSON.parse(readFileSync(join(app, "package-lock.json"), "utf8")) as { packages: Record<string, { version?: string }> };
    const installed = (n: string) => lock.packages[`node_modules/${n}`]?.version;
    expect(installed("vitest")).toBe(installed("@vitest/coverage-v8"));
    expect(lock.packages["node_modules/nodemon"]).toBeUndefined();
    const ls = npm(["ls", "--all"], app);
    expect(ls.status, `npm ls reports problems (invalid or missing peer dependencies)\n${show(ls)}`).toBe(0);
    // The binaries that need an install script work after install, not just npm's exit code.
    expect(npm(["install-scripts", "ls"], app).stdout).not.toMatch(/esbuild/);
    if (c.language === "ts") {
      if (!win) {
        const esbuild = sh(join(app, "node_modules/esbuild/bin/esbuild"), ["--version"], app);
        expect(esbuild.status, show(esbuild)).toBe(0);
        expect(esbuild.stdout.trim()).toMatch(/^\d+\.\d+\.\d+$/);
      }
      const tsx = sh(node, [join(app, "node_modules/tsx/dist/cli.mjs"), "-e", "const x: number = 41; console.log(x + 1)"], app);
      expect(tsx.stdout.trim(), show(tsx)).toBe("42");
    }
  });

  it("reinstalls reproducibly with npm ci and the lockfile does not change", () => {
    const lockFile = join(app, "package-lock.json");
    const before = sha(lockFile);
    rmSync(join(app, "node_modules"), { recursive: true, force: true });
    const r = npm(["ci", "--no-fund"], app);
    expect(r.status, show(r)).toBe(0);
    expect(sha(lockFile)).toBe(before);
    expectCleanAudit(app, `${name} after npm ci`);
  }, 300_000);

  it("keeps .env out of git and out of the first commit, and generates a unique secret", () => {
    expect(readFileSync(join(app, ".gitignore"), "utf8")).toMatch(/^\.env$/m);
    expect(existsSync(join(app, ".env"))).toBe(true);
    const tracked = git(["ls-files"], app).stdout.split("\n");
    expect(tracked).not.toContain(".env");
    expect(tracked).toContain(".env.example");
    expect(git(["check-ignore", ".env"], app).status).toBe(0);
    expect(git(["log", "--format=%s"], app).stdout, "initial commit").toContain("Initial commit");
    const secret = /^JWT_SECRET=(.+)$/m.exec(readFileSync(join(app, ".env"), "utf8"))?.[1];
    if (!c.auth) return expect(secret).toBeUndefined();
    expect(secret!.length).toBeGreaterThanOrEqual(48);
    const history = git(["log", "--all", "-p"], app).stdout;
    expect(history).not.toContain(secret!);
    secrets.set(name, secret!);
  });
});

describe("secrets are unique per project", () => {
  it("never reuses a JWT secret", () => {
    const values = [...secrets.values()];
    expect(values.length).toBe(2);
    expect(new Set(values).size).toBe(values.length);
  });
});

describe.each([
  { name: "ts-esm-none", entry: "src/server.ts" },
  { name: "js-cjs-none", entry: "src/server.js" },
])("npm run dev starts $name and answers its health endpoint", (v) => {
  it("serves /health while watching files", async () => {
    const app = join(work, v.name);
    const child = spawn("npm", ["run", "dev"], { cwd: app, shell: win, env: { ...process.env, PORT: "0", NODE_ENV: "development" }, detached: !win });
    let log = "";
    child.stdout.on("data", (d) => (log += d));
    child.stderr.on("data", (d) => (log += d));
    try {
      const port = await new Promise<number>((res, rej) => {
        const t = setTimeout(() => rej(new Error("dev server did not start\n" + log)), 30_000);
        const iv = setInterval(() => {
          const m = /"port":(\d+)/.exec(log);
          if (m) {
            clearTimeout(t);
            clearInterval(iv);
            res(Number(m[1]));
          }
        }, 100);
        child.once("exit", () => rej(new Error("dev server exited early\n" + log)));
      });
      expect((await fetch(`http://127.0.0.1:${port}/health`)).status).toBe(200);
      expect((await fetch(`http://127.0.0.1:${port}/api/rhea`)).status).toBe(200);
    } finally {
      if (win) spawnSync("taskkill", ["/pid", String(child.pid), "/t", "/f"]);
      else if (child.pid) {
        try {
          process.kill(-child.pid, "SIGKILL");
        } catch {
          /* already gone */
        }
      }
      // A surviving grandchild would keep these pipes open and stop the test run from ever exiting.
      child.stdout.destroy();
      child.stderr.destroy();
      child.unref();
    }
  }, 60_000);
});
